package com.example.audioinsight.ui;

import android.app.AlertDialog;
import android.content.*;
import android.graphics.Typeface;
import android.media.MediaPlayer;
import android.net.Uri;
import android.os.*;
import android.text.*;
import android.view.*;
import android.widget.*;
import com.example.audioinsight.data.*;
import org.json.*;
import java.io.OutputStream;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** A single persisted record: real media playback, editable timed transcript and summaries. */
public class ResultActivity extends UiActivity {
    private long id;
    private RecordInfo record;
    private String signature="",query="",mode="全部";
    private LinearLayout segmentsBox,information;
    private TextView playerState,position,selectedLabel;
    private Button play;
    private SeekBar seek;
    private MediaPlayer audio;
    private VideoView video;
    private boolean prepared,wasPlaying;
    private int rememberedPosition;
    private int structureRevision=-1,rangeEndMs=-1;
    private final LinkedHashSet<Integer> selected=new LinkedHashSet<>();
    private final Handler handler=new Handler(Looper.getMainLooper());
    private final Runnable ticker=new Runnable(){public void run(){if(prepared){int at=current();if(rangeEndMs>=0&&at>=rangeEndMs){pause();wasPlaying=false;rangeEndMs=-1;}if(seek!=null)seek.setProgress(at);if(position!=null)position.setText(duration(at/1000.0)+" / "+duration(total()/1000.0));if(play!=null)play.setText(isPlaying()?"Ⅱ  暂停":"▶  播放原声");}handler.postDelayed(this,350);}};
    @Override public void onCreate(Bundle b){super.onCreate(b);id=getIntent().getLongExtra("record_id",-1);if(b!=null){rememberedPosition=b.getInt("position");query=b.getString("query","");mode=b.getString("mode","全部");}page("识别结果","正在读取本机记录…",true,-1);note("请稍候…");}
    @Override protected void onResume(){super.onResume();load();handler.removeCallbacks(ticker);handler.post(ticker);}
    @Override protected void onRecordsChanged(){load();}
    private void load(){if(id<0){error("没有找到这条记录，请返回历史重新选择。");return;}repo.loadRecord(id,new Callback<RecordInfo>(){public void onSuccess(RecordInfo value){if(isFinishing()||isDestroyed()||!active)return;int incomingRevision=value.result().optInt("segmentStructureRevision",0);if(structureRevision>=0&&structureRevision!=incomingRevision)selected.clear();structureRevision=incomingRevision;record=value;String fresh=value.title+value.status+value.message+value.favorite+value.resultJson;if(!fresh.equals(signature)){signature=fresh;render();}}public void onError(String m){error(m);}});}
    private void render(){if(prepared){rememberedPosition=current();wasPlaying=isPlaying();}release();page("识别结果",when(record.createdAt)+" · "+RecordInfo.statusLabel(record.status),true,-1);LinearLayout intro=card();TextView title=text(record.title,22,INK);title.setTypeface(null,Typeface.BOLD);intro.addView(title);TextView meta=text(duration(record.duration)+(record.isVideo()?" · 视频":" · 音频")+"   /   "+RecordInfo.statusLabel(record.status),12,CYAN);meta.setPadding(0,dp(10),0,dp(10));intro.addView(meta);if(record.message!=null&&!record.message.isEmpty())intro.addView(text(record.message,13,MUTED));pair(intro,record.favorite?"★  已收藏":"☆  收藏",v->repo.updateMeta(id,record.title,!record.favorite,new Callback<RecordInfo>(){public void onSuccess(RecordInfo r){record=r;load();}public void onError(String m){error(m);}}),"记录管理",v->manage(record));if(!record.hasResult()){String action="Draft".equalsIgnoreCase(record.status)||"Failed".equalsIgnoreCase(record.status)||"UploadInterrupted".equalsIgnoreCase(record.status)?"提交并整理":"重新连接 / 刷新状态";addButton(intro,action,true,v->{if(action.equals("提交并整理"))repo.submit(id,resultCallback());else repo.refresh(id,resultCallback());});note("记录已保存在本机。识别进度会自动更新；离开此页后可在历史中继续查看。");}else addButton(intro,"刷新服务结果",false,v->repo.refresh(id,resultCallback()));setupPlayer();if(record.hasResult()){pair(body,"复制全文与重点",v->copy(record.title,exportText()),"导出文本文件",v->export());addButton(body,"查看音高与发言分析",false,v->startActivity(new Intent(this,StatsActivity.class).putExtra("record_id",id)));buildContent();}else note("完成识别后，将在这里显示分句转写、摘要、关键词和待办。");}
    private Callback<RecordInfo> resultCallback(){return new Callback<RecordInfo>(){public void onSuccess(RecordInfo r){record=r;load();}public void onError(String m){error(m);}};}
    private void setupPlayer(){LinearLayout c=card();c.addView(text("原声回放",17,INK));playerState=text("正在准备播放…",12,MUTED);playerState.setPadding(0,dp(8),0,dp(8));c.addView(playerState);String source=repo.mediaUrl(record);if(source==null||source.isEmpty()){playerState.setText("原始文件暂不可用，请检查电脑服务连接。");return;}if(record.isVideo()){video=new VideoView(this);video.setBackgroundColor(0xff080b15);c.addView(video,new LinearLayout.LayoutParams(-1,dp(190)));video.setOnPreparedListener(mp->{prepared=true;ready();});video.setOnCompletionListener(mp->{wasPlaying=false;if(play!=null)play.setText("▶  播放原声");});video.setOnErrorListener((mp,w,e)->{playError();return true;});video.setVideoURI(Uri.parse(source));}else{try{audio=new MediaPlayer();audio.setDataSource(this,Uri.parse(source));audio.setOnPreparedListener(mp->{prepared=true;ready();});audio.setOnCompletionListener(mp->{wasPlaying=false;if(play!=null)play.setText("▶  播放原声");});audio.setOnErrorListener((mp,w,e)->{playError();return true;});audio.prepareAsync();}catch(Exception e){playerState.setText("暂时无法播放。请检查原文件和服务连接。");}}
        position=text("00:00 / "+duration(record.duration),12,MUTED);c.addView(position);seek=new SeekBar(this);seek.setMinimumHeight(dp(48));c.addView(seek,new LinearLayout.LayoutParams(-1,dp(48)));seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int progress,boolean user){if(user&&prepared){rangeEndMs=-1;seekTo(progress);}}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}});play=addButton(c,"▶  播放原声",true,v->{if(!prepared)return;rangeEndMs=-1;if(isPlaying()){pause();wasPlaying=false;}else{start();wasPlaying=true;}});play.setEnabled(prepared);if(prepared)ready();}
    private void ready(){if(play==null||seek==null)return;seek.setMax(Math.max(1,total()));play.setEnabled(true);playerState.setText("点击分句可跳转到对应原声位置");if(rememberedPosition>0)seekTo(rememberedPosition);if(wasPlaying)start();}
    private void playError(){prepared=false;if(playerState!=null)playerState.setText("无法播放此文件。请检查文件格式和服务连接。");if(play!=null)play.setEnabled(false);}
    private int current(){try{return video!=null?video.getCurrentPosition():audio!=null?audio.getCurrentPosition():0;}catch(Exception e){return 0;}}
    private int total(){try{return video!=null?video.getDuration():audio!=null?audio.getDuration():0;}catch(Exception e){return 0;}}
    private boolean isPlaying(){try{return video!=null?video.isPlaying():audio!=null&&audio.isPlaying();}catch(Exception e){return false;}}
    private void start(){try{if(video!=null)video.start();else if(audio!=null)audio.start();}catch(Exception e){playError();}}
    private void pause(){try{if(video!=null)video.pause();else if(audio!=null)audio.pause();}catch(Exception ignored){}}
    private void seekTo(int ms){try{if(video!=null)video.seekTo(ms);else if(audio!=null)audio.seekTo(ms);}catch(Exception ignored){}}
    private void jump(double seconds,double end){if(!prepared){toast("原声还未准备好，请稍候");return;}rangeEndMs=end>seconds?(int)(end*1000):-1;seekTo((int)(seconds*1000));start();wasPlaying=true;toast("已跳转至 "+duration(seconds));}
    private void release(){prepared=false;if(audio!=null){audio.release();audio=null;}if(video!=null){video.stopPlayback();video=null;}play=null;seek=null;}

    private void buildContent(){JSONObject data=record.result();JSONArray warnings=data.optJSONArray("warnings");if(warnings!=null&&warnings.length()>0){TextView warning=note("提示："+join(warnings,"；"));warning.setTextColor(0xffffc07a);}label("阅读与整理");HorizontalScrollView filterScroll=new HorizontalScrollView(this);filterScroll.setHorizontalScrollBarEnabled(false);LinearLayout filters=row();String[] choices={"全部","摘要重点","待办事项","需核对"};for(String name:choices){Button b=button(name,name.equals(mode));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,dp(48));p.rightMargin=dp(8);filters.addView(b,p);b.setOnClickListener(v->{mode=name;for(int i=0;i<filters.getChildCount();i++){Button item=(Button)filters.getChildAt(i);boolean checked=item.getText().toString().equals(mode);item.setBackground(rounded(checked?CYAN:0xff2a304b,0));item.setTextColor(checked?BG:INK);}renderInfo();renderSegments();});}filterScroll.addView(filters);body.addView(filterScroll);information=column();body.addView(information);LinearLayout searchCard=card();EditText search=input("搜索转写中的关键词");search.setText(query);searchCard.addView(search);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){query=s.toString();renderSegments();}public void afterTextChanged(Editable e){}});selectedLabel=text("勾选分句，可单独整理这部分内容",12,MUTED);selectedLabel.setPadding(0,dp(12),0,0);searchCard.addView(selectedLabel);addButton(searchCard,"整理已选分句",false,v->summarizeSelected());segmentsBox=column();body.addView(segmentsBox);renderInfo();renderSegments();}
    private LinearLayout localCard(LinearLayout host,String title){LinearLayout c=column();c.setPadding(dp(16),dp(16),dp(16),dp(16));c.setBackground(rounded(PANEL,0));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(12);p.bottomMargin=dp(4);host.addView(c,p);if(title!=null){TextView t=text(title,17,INK);t.setTypeface(null,Typeface.BOLD);c.addView(t);}return c;}
    private void renderInfo(){if(information==null||record==null)return;information.removeAllViews();if(mode.equals("需核对"))return;JSONObject info=record.result().optJSONObject("importantInfo");if(info==null){LinearLayout c=localCard(information,"重点整理");c.addView(text("本次尚未返回摘要与待办。",14,MUTED));addButton(c,"重新整理重点",false,v->repo.retrySummary(id,resultCallback()));return;}if(!mode.equals("待办事项")){LinearLayout c=localCard(information,"内容摘要");TextView summary=text(nonempty(info.optString("summary"),"本次尚未生成摘要。"),15,MUTED);summary.setTextIsSelectable(true);summary.setPadding(0,dp(12),0,dp(10));c.addView(summary);JSONArray keywords=info.optJSONArray("keywords");if(keywords!=null&&keywords.length()>0){c.addView(text("关键词  ·  "+join(keywords,"  /  "),13,CYAN));}addArray(c,"主要事实",info.optJSONArray("facts"));addArray(c,"已作决定",info.optJSONArray("decisions"));addArray(c,"待讨论问题",info.optJSONArray("questions"));addButton(c,"重新整理重点",false,v->repo.retrySummary(id,resultCallback()));}if(!mode.equals("摘要重点")){LinearLayout c=localCard(information,"待办事项");JSONArray tasks=info.optJSONArray("action_items");if(tasks==null||tasks.length()==0)c.addView(text("没有提取到明确的待办事项。",14,MUTED));else for(int i=0;i<tasks.length();i++){JSONObject task=tasks.optJSONObject(i);if(task==null)continue;TextView line=text("□  "+task.optString("task")+"\n负责人："+nonempty(task.optString("owner"),"未明确")+"  ·  期限："+nonempty(task.optString("deadline"),"未明确"),14,MUTED);line.setPadding(0,dp(12),0,dp(8));line.setTextIsSelectable(true);c.addView(line);}}}
    private void addArray(LinearLayout c,String title,JSONArray a){if(a==null||a.length()==0)return;TextView line=text(title+"\n• "+join(a,"\n• "),14,MUTED);line.setPadding(0,dp(14),0,0);line.setTextIsSelectable(true);c.addView(line);}
    private void renderSegments(){if(segmentsBox==null||record==null)return;segmentsBox.removeAllViews();selectedLabel.setText(selected.isEmpty()?"勾选分句，可单独整理这部分内容":"已选择 "+selected.size()+" 个分句");if(mode.equals("摘要重点")||mode.equals("待办事项"))return;JSONArray segments=record.result().optJSONArray("segments");if(segments==null||segments.length()==0){LinearLayout c=localCard(segmentsBox,"完整转写");TextView full=text(record.transcript(),15,INK);full.setTextIsSelectable(true);c.addView(full);return;}int shown=0;String needle=query.trim().toLowerCase(Locale.ROOT);for(int i=0;i<segments.length();i++){JSONObject segment=segments.optJSONObject(i);if(segment==null)continue;String content=segment.optString("text","");boolean uncertain=needsReview(segment);if(!needle.isEmpty()&&!content.toLowerCase(Locale.ROOT).contains(needle))continue;if(mode.equals("需核对")&&!uncertain)continue;final int index=i;LinearLayout c=localCard(segmentsBox,null);LinearLayout line=row();CheckBox check=new CheckBox(this);check.setButtonTintList(android.content.res.ColorStateList.valueOf(CYAN));check.setChecked(selected.contains(i));check.setContentDescription("选择第 "+(i+1)+" 个分句");line.addView(check,new LinearLayout.LayoutParams(dp(48),dp(48)));String speaker=speakerLabel(segment.optString("speakerId",""));TextView time=text(duration(segment.optDouble("start",0))+" – "+duration(segment.optDouble("end",0))+"  ·  "+speaker,11,CYAN);line.addView(time,new LinearLayout.LayoutParams(0,-2,1));c.addView(line);check.setOnCheckedChangeListener((b,on)->{if(on)selected.add(index);else selected.remove(index);selectedLabel.setText(selected.isEmpty()?"勾选分句，可单独整理这部分内容":"已选择 "+selected.size()+" 个分句");});TextView words=text(content,16,uncertain?0xffffd1a1:INK);words.setPadding(0,dp(6),0,dp(10));words.setMinHeight(dp(48));words.setOnClickListener(v->jump(segment.optDouble("start",0),segment.optDouble("end",0)));c.addView(words);if(uncertain){JSONObject review=segment.optJSONObject("review");JSONArray reasons=review==null?segment.optJSONArray("reviewReasons"):review.optJSONArray("reasons");TextView flag=text("需听原声核对"+(reasons!=null&&reasons.length()>0?" · "+join(reasons,"；"):""),11,0xffffc07a);c.addView(flag);}pair(c,"▶  听这句",v->jump(segment.optDouble("start",0),segment.optDouble("end",0)),"修订文字",v->edit(index,content));shown++;}if(shown==0){TextView empty=text(mode.equals("需核对")?"没有符合条件的疑难分句。\n这些标记只是复核线索，请以原声为准。":"没有找到匹配的分句。",14,MUTED);empty.setPadding(0,dp(24),0,dp(24));segmentsBox.addView(empty);}}
    private String speakerLabel(String id){JSONArray speakers=record.result().optJSONArray("speakers");if(speakers!=null)for(int i=0;i<speakers.length();i++){JSONObject s=speakers.optJSONObject(i);if(s!=null&&id.equals(s.optString("id")))return s.optString("label",s.optString("code","发言者"));}return id.isEmpty()||id.equals("null")?"未标注":id.replace("speaker_","发言者 ");}
    private boolean needsReview(JSONObject segment){JSONObject review=segment.optJSONObject("review");if(review!=null&&review.optBoolean("needsReview"))return true;if(segment.optBoolean("lowConfidence"))return true;JSONArray words=segment.optJSONArray("words");if(words!=null)for(int i=0;i<words.length();i++){JSONObject word=words.optJSONObject(i);if(word!=null&&word.optBoolean("uncertain"))return true;}return false;}
    private void edit(int index,String original){final int expectedRevision=record.result().optInt("segmentStructureRevision",0);EditText e=input("修订分句文字");e.setSingleLine(false);e.setMinLines(4);e.setMaxLines(8);e.setText(original);LinearLayout wrap=column();wrap.setPadding(dp(20),dp(12),dp(20),dp(12));wrap.addView(e);wrap.addView(text("修改后会保留原来的时间位置。",12,MUTED));new AlertDialog.Builder(this).setTitle("修订分句").setView(wrap).setNegativeButton("取消",null).setPositiveButton("保存",(d,n)->{String value=e.getText().toString().trim();if(value.isEmpty()){toast("分句内容不能为空");return;}repo.editSegment(id,index,value,original,expectedRevision,resultCallback());}).show();}
    private void summarizeSelected(){if(selected.isEmpty()){toast("请先勾选需要整理的分句");return;}toast("正在整理已选内容…");repo.summarizeSelection(id,new ArrayList<>(selected),record.result().optInt("segmentStructureRevision",0),new Callback<JSONObject>(){public void onSuccess(JSONObject value){if(!active||isFinishing()||isDestroyed())return;JSONObject info=value.optJSONObject("importantInfo");if(info==null)info=value;String content=summaryText(info);if(content.trim().isEmpty())content=value.toString();final String output=content;new AlertDialog.Builder(ResultActivity.this).setTitle("选中内容的重点").setMessage(output).setNegativeButton("关闭",null).setPositiveButton("复制",(d,n)->copy("分句重点",output)).show();}public void onError(String m){error(m);}});}
    private String summaryText(JSONObject info){StringBuilder b=new StringBuilder();if(info==null)return "";String summary=info.optString("summary","");if(!summary.isEmpty())b.append("摘要\n").append(summary).append("\n\n");String[] keys={"keyPoints","keywords","facts","decisions","questions"};String[] labels={"片段重点","关键词","主要事实","已作决定","待讨论问题"};for(int i=0;i<keys.length;i++){JSONArray a=info.optJSONArray(keys[i]);if(a!=null&&a.length()>0)b.append(labels[i]).append("\n").append(join(a,"\n")).append("\n\n");}JSONArray tasks=info.optJSONArray("action_items");if(tasks!=null&&tasks.length()>0){b.append("待办事项\n");for(int i=0;i<tasks.length();i++){JSONObject t=tasks.optJSONObject(i);if(t!=null)b.append("• ").append(t.optString("task")).append("（负责人：").append(nonempty(t.optString("owner"),"未明确")).append("；期限：").append(nonempty(t.optString("deadline"),"未明确")).append("）\n");}}return b.toString();}
    private String exportText(){StringBuilder b=new StringBuilder(record.title+"\n"+when(record.createdAt)+"\n\n完整转写\n");JSONArray segments=record.result().optJSONArray("segments");if(segments!=null&&segments.length()>0)for(int i=0;i<segments.length();i++){JSONObject s=segments.optJSONObject(i);if(s!=null)b.append("[").append(duration(s.optDouble("start",0))).append(" – ").append(duration(s.optDouble("end",0))).append("] ").append(speakerLabel(s.optString("speakerId",""))).append("\n").append(s.optString("text")).append("\n\n");}else b.append(record.transcript()).append("\n\n");b.append(summaryText(record.result().optJSONObject("importantInfo")));return b.toString();}
    private void export(){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("text/plain");i.putExtra(Intent.EXTRA_TITLE,record.title.replaceAll("[\\\\/:*?\"<>|]","_")+".txt");try{startActivityForResult(i,82);}catch(ActivityNotFoundException e){error("设备没有可用的文件保存位置选择器。");}}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=82||result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();String content=exportText();new Thread(()->{try(OutputStream out=getContentResolver().openOutputStream(uri)){if(out==null)throw new java.io.IOException();out.write(content.getBytes(StandardCharsets.UTF_8));runOnUiThread(()->toast("文本已导出到选择的位置"));}catch(Exception e){runOnUiThread(()->error("导出失败，请重新选择保存位置。"));}},"export-text").start();}
    private String join(JSONArray a,String separator){StringBuilder b=new StringBuilder();for(int i=0;i<a.length();i++){String s=a.optString(i,"");if(s.isEmpty())continue;if(b.length()>0)b.append(separator);b.append(s);}return b.toString();}
    private String nonempty(String s,String fallback){return s==null||s.trim().isEmpty()||s.equals("null")?fallback:s;}
    @Override protected void onStop(){if(prepared){rememberedPosition=current();wasPlaying=isPlaying();}handler.removeCallbacks(ticker);release();signature="";super.onStop();}
    @Override protected void onDestroy(){handler.removeCallbacks(ticker);release();super.onDestroy();}
    @Override protected void onSaveInstanceState(Bundle b){b.putInt("position",current());b.putString("query",query);b.putString("mode",mode);super.onSaveInstanceState(b);}
}
